// Generates src/content/screen-pricing.ts from the admin screen-price store (data/seo.json →
// .screenPrices). Both the blog cost-guides AND the service-page price tables import from the
// generated file, so editing prices once in /admin/screen-prices keeps every surface in sync.
// Runs in predev/prebuild (see package.json). Falls back to keeping the existing generated file
// untouched if the store has no screen prices (protects against a build without the data file).
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const STORE = process.env.SEO_DB || path.join(ROOT, "data", "seo.json");
const OUT = path.join(ROOT, "src", "content", "screen-pricing.ts");

function loadScreenPrices() {
  try {
    const d = JSON.parse(fs.readFileSync(STORE, "utf8"));
    return Array.isArray(d.screenPrices) ? d.screenPrices : [];
  } catch {
    return [];
  }
}

const all = loadScreenPrices().slice().sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0) || a.id - b.id);

if (!all.length) {
  console.warn(`[gen-screen-prices] no screen prices in store (${STORE}); keeping existing ${path.relative(ROOT, OUT)}`);
  process.exit(0);
}

const iphone  = all.filter((r) => r.device === "iphone");
const ipad    = all.filter((r) => r.device === "ipad");
const macbook = all.filter((r) => r.device === "macbook");

const fmt = (arr) =>
  arr
    .map((r) =>
      `  { model: ${JSON.stringify(r.model)}, price: ${r.price}, apple_price: ${r.apple_price ?? 0}, note: ${JSON.stringify(r.note ?? "")} },`
    )
    .join("\n");

const out = `// AUTO-GENERATED by scripts/gen-screen-prices.cjs from data/seo.json — do not edit by hand.
// Edit prices in /admin/screen-prices, then rebuild to apply everywhere.
// Prices are AED, VAT-inclusive starting prices for that model's panel swap.
export type ScreenPrice = { model: string; price: number; apple_price: number; note: string };

export const IPHONE_SCREEN_PRICES: ScreenPrice[] = [
${fmt(iphone)}
];

export const IPAD_SCREEN_PRICES: ScreenPrice[] = [
${fmt(ipad)}
];

export const MACBOOK_SCREEN_PRICES: ScreenPrice[] = [
${fmt(macbook)}
];
`;

fs.writeFileSync(OUT, out);
console.log(`[gen-screen-prices] wrote screen-pricing.ts (iPhone ${iphone.length}, iPad ${ipad.length}, MacBook ${macbook.length} models)`);
